import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.Dc2C-di8.js";var i=JSON.parse(`{"title":"Homebrew Bottle Releases","description":"","frontmatter":{"id":"decision.0004","title":"Homebrew Bottle Releases","status":"accepted","established-by":"user.2026-10-29","supersedes":[]},"headers":[],"relativePath":"decisions/0004-homebrew-bottle-releases.md","filePath":"decisions/0004-homebrew-bottle-releases.md"}`),a={name:`decisions/0004-homebrew-bottle-releases.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="homebrew-bottle-releases" tabindex="-1">Homebrew Bottle Releases <a class="header-anchor" href="#homebrew-bottle-releases" aria-label="Permalink to “Homebrew Bottle Releases”">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><p>Recon publishes versioned GitHub releases and a plain formula in <code>markmals/homebrew-tap</code>. The formula builds and bottles the CLI with its matched native inspection artifacts, making Homebrew the canonical local installation and upgrade path.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Recon is a macOS CLI, but native inspection also needs a loader, a universal Apple-silicon helper, and the helper&#39;s build identity beside the executable. Installing only <code>target/release/recon</code> leaves those operations unavailable. The personal tap already builds plain formulae and publishes CI-built bottles through <code>brew test-bot</code> and <code>brew pr-pull</code>; a cask or a manually copied binary would bypass that established release path.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Tag each official Recon release as <code>v&lt;version&gt;</code>, matching the <code>recon</code> crate version, and create a GitHub release for that tag. Distribute Recon through <code>markmals/homebrew-tap</code> as <code>Formula/recon.rb</code>, not as a cask.</p><p>The formula builds from the release&#39;s Git tag and pinned revision with the Rust and Apple toolchains. It builds the CLI, loader, and helper; installs <code>recon</code>, <code>recon-loader</code>, <code>recon-helper.dylib</code>, and <code>recon-helper.build-id</code> together in <code>libexec</code>; and exposes only the CLI through a <code>bin</code> exec script. Tap pull requests use the existing macOS bottle matrix and formula tests. The <code>pr-pull</code> workflow publishes those bottles and updates the formula rather than checking bottle binaries into either repository.</p><p>Homebrew is the canonical local installation. Release upgrades update the crate version, tag and GitHub release first, then update the formula&#39;s tag and revision and repeat bottle validation and publication.</p><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to “Rationale”">​</a></h2><p>A source-built formula preserves Recon&#39;s native build requirements while bottles make normal installation fast and repeatable. Keeping all four artifacts in one versioned prefix preserves the executable-adjacent lookup and helper build compatibility contract. Reusing the tap&#39;s existing automation avoids a second release system and provides the same review and bottle-publication controls as the other CLI formulae.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><ul><li>A Homebrew cask containing a manually assembled binary archive — unsuitable for a CLI and duplicates the tap&#39;s existing bottle infrastructure.</li><li>Installing only the Rust executable — leaves native inspection without its required loader, helper, and build identity.</li><li>Checking prebuilt binaries into the Recon repository or tap — obscures provenance and bypasses per-macOS-version bottle builds.</li><li>A Recon-owned release workflow that duplicates bottle publication — adds automation without replacing any missing capability in the tap&#39;s existing <code>test-bot</code>/<code>pr-pull</code> flow.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><h3 id="good" tabindex="-1">Good <a class="header-anchor" href="#good" aria-label="Permalink to “Good”">​</a></h3><ul><li><code>brew install markmals/tap/recon</code> installs every artifact needed by the released CLI.</li><li>Homebrew owns subsequent local upgrades and removal.</li><li>Bottle provenance and macOS compatibility are checked through pull request CI.</li><li>The CLI remains the only command exposed on <code>PATH</code>; native implementation artifacts stay in <code>libexec</code>.</li></ul><h3 id="bad" tabindex="-1">Bad <a class="header-anchor" href="#bad" aria-label="Permalink to “Bad”">​</a></h3><ul><li>A release spans the Recon and tap repositories and must be tagged before the tap formula can fetch its source.</li><li>Each release requires formula tag and revision updates and new bottles for the supported macOS runners.</li><li>Source builds require Rust, Node, and Apple build tools even though ordinary bottle installations do not compile Recon.</li><li>Homebrew&#39;s ad-hoc-signed installation does not replace the separate privacy grants or research-host requirements of native inspection.</li></ul><h2 id="revision-history" tabindex="-1">Revision history <a class="header-anchor" href="#revision-history" aria-label="Permalink to “Revision history”">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th><th>Authority</th></tr></thead><tbody><tr><td>2026-10-29</td><td>Accepted GitHub releases and the bottled Homebrew formula as Recon&#39;s distribution path.</td><td>user.2026-10-29</td></tr></tbody></table>`,20)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};